19:   bool valid_reference_input(const nav_msgs::msg::Path &path, double body_height,
20:                              const Eigen::Vector3d &odom_position,
21:                              const Eigen::Vector3d &used_velocity)
22:   {
23:     if (path.header.frame_id != "camera_init" || path.poses.empty() ||
24:         !std::isfinite(body_height) || !odom_position.allFinite() || !used_velocity.allFinite())
25:       return false;
26:     Eigen::Vector3d previous = odom_position;
27:     for (const auto &pose : path.poses)
28:     {
29:       if (!pose.header.frame_id.empty() && pose.header.frame_id != "camera_init") return false;
30:       const auto &p = pose.pose.position;
31:       const auto &q = pose.pose.orientation;
32:       Eigen::Vector3d body_point(p.x, p.y, p.z + body_height);
33:       if (!body_point.allFinite() || !std::isfinite(p.z) || !std::isfinite(q.x) ||
34:           !std::isfinite(q.y) || !std::isfinite(q.z) || !std::isfinite(q.w) ||
35:           (body_point - previous).norm() <= 1e-6)
36:         return false; // A zero-duration segment makes the polynomial fit singular.
37:       previous = body_point;
38:     }
39:     return true;
40:   }

