508:   void SCANReplanFSM::pathCallback(const nav_msgs::msg::Path::ConstSharedPtr &msg)
509:   {
510:     if (navi_mode_ != NAVI_MODE::REFERENCE_PATH) return;
511:     invalidateReference("replacement received");
512:     if (!msg || !have_odom_ ||
513:         (external_reference_protocol_ && msg->poses.size() > 4096) || // Explicit R85 input budget; no simplification.
514:         !valid_reference_input(*msg, body_height_, odom_pos_,
515:                                measured_start_.velocity(go2_execution_frozen_)))
516:     {
517:       RCLCPP_WARN(node_->get_logger(), "Rejected reference: frame/finite/odometry/nonzero-segment validation failed");
518:       return;
519:     }

594:   void SCANReplanFSM::odometryCallback(const nav_msgs::msg::Odometry::ConstSharedPtr &msg)
595:   {
596:     last_odom_stamp_ns_ = rclcpp::Time(msg->header.stamp).nanoseconds();
597:     last_odom_receive_time_ = std::chrono::steady_clock::now();
598:     odom_pos_(0) = msg->pose.pose.position.x;
599:     odom_pos_(1) = msg->pose.pose.position.y;
600:     odom_pos_(2) = msg->pose.pose.position.z;
601: 
602:     if (navi_mode_ == NAVI_MODE::MANUAL_TARGET && !rviz_height_ready_)
603:     {
604:       rviz_goal_height_ = odom_pos_(2);
605:       rviz_height_ready_ = true;
606:       RCLCPP_INFO(node_->get_logger(), "Set RViz goal height from initial body_pose z: %.3f", rviz_goal_height_);
607:     }
608: 
609:     odom_vel_(0) = msg->twist.twist.linear.x;
610:     odom_vel_(1) = msg->twist.twist.linear.y;
611:     odom_vel_(2) = msg->twist.twist.linear.z;
612:     measured_start_.update(odom_vel_, rclcpp::Time(msg->header.stamp).nanoseconds(), go2_execution_frozen_);
613: 
614:     //odom_acc_ = estimateAcc( msg );
615: 
616:     odom_orient_.w() = msg->pose.pose.orientation.w;
617:     odom_orient_.x() = msg->pose.pose.orientation.x;
618:     odom_orient_.y() = msg->pose.pose.orientation.y;
619:     odom_orient_.z() = msg->pose.pose.orientation.z;
620: 
621:     have_odom_ = true;
622:     publishSelfInflationMarker();
623:     if (navi_mode_ == NAVI_MODE::PRESET_TARGET && !preset_started_)
624:     {
625:       preset_started_ = true;
626:       planGlobalTrajbyGivenWps();
627:     }
628:   }

666:   void SCANReplanFSM::publishSelfInflationMarker()
667:   {
668:     const double radius = std::max(0.0, self_double_cylinder_radius_);
669:     const double z_up = std::max(0.0, self_inflation_z_up_);
670:     const double z_down = std::max(0.0, self_inflation_z_down_);
671:     const double height = std::max(1e-3, z_up + z_down);
672: 
673:     visualization_msgs::msg::Marker marker;
674:     marker.header.frame_id = self_inflation_frame_id_.empty() ? "world" : self_inflation_frame_id_;
675:     marker.header.stamp = node_->now();
676:     marker.ns = "self_inflation";
677:     marker.type = visualization_msgs::msg::Marker::CYLINDER;
678:     marker.action = visualization_msgs::msg::Marker::ADD;
679:     marker.pose.orientation.w = 1.0;
680:     marker.scale.x = 2.0 * radius;
681:     marker.scale.y = 2.0 * radius;
682:     marker.scale.z = height;
683:     marker.color.r = 0.1;
684:     marker.color.g = 0.6;
685:     marker.color.b = 1.0;
686:     marker.color.a = 0.4;
687:     marker.lifetime = rclcpp::Duration::from_seconds(0.2);
688: 
689:     Eigen::Vector3d center = odom_pos_;
690:     center(2) += 0.5 * (z_up - z_down);
691: 
692:     Eigen::Vector3d heading(std::cos(getOdomYaw()), std::sin(getOdomYaw()), 0.0);
693:     Eigen::Vector3d front = center + self_double_cylinder_offset_ * heading;
694:     Eigen::Vector3d rear = center - self_double_cylinder_offset_ * heading;
695: 
696:     marker.id = 0;
697:     marker.pose.position.x = front(0);
698:     marker.pose.position.y = front(1);
699:     marker.pose.position.z = front(2);
700:     self_inflation_pub_->publish(marker);
701: 
702:     marker.id = 1;
703:     marker.pose.position.x = rear(0);
704:     marker.pose.position.y = rear(1);
705:     marker.pose.position.z = rear(2);
706:     self_inflation_pub_->publish(marker);

