7: namespace scan_planner {
8: // Timestamp-based measured world velocity. Never inherit unexecuted spline
9: // derivatives after a turn/stop, and never change the measured start position.
10: class MeasuredStartState {
11: public:
12:   double max_speed{.12};
13:   double time_constant{.4};
14:   void update(const Eigen::Vector3d &velocity, int64_t stamp, bool frozen) {
15:     if (!velocity.allFinite() || stamp <= stamp_) return;
16:     Eigen::Vector3d observed = velocity;
17:     if (observed.norm() > max_speed) observed *= max_speed/observed.norm();
18:     const double dt = stamp_ < 0 ? 0. : (stamp-stamp_)*1e-9;
19:     stamp_ = stamp;
20:     if (frozen) { filtered_.setZero(); ready_=true; return; }
21:     if (!ready_) filtered_=observed;
22:     else filtered_ += (-std::expm1(-dt/time_constant))*(observed-filtered_);
23:     ready_=true;
24:   }
25:   Eigen::Vector3d velocity(bool frozen) const {
26:     return frozen ? Eigen::Vector3d::Zero() : filtered_;
27:   }
28:   void stop() { filtered_.setZero(); }
29: private:
30:   Eigen::Vector3d filtered_{Eigen::Vector3d::Zero()};
31:   int64_t stamp_{-1};
32:   bool ready_{false};
33: };
34: } // namespace scan_planner
